    decreases logIndexUpper - logIndexLower,
{
    if logIndexLower == logIndexUpper {
    } else {
        if log.index(logIndexLower).node_id == nodeId {
            LogRangeMatchesQueue_update_change(
                queue,
                log,
                queueIndex + 1,
                logIndexLower + 1,
                logIndexUpper,
                nodeId,
                updates1,
                updates2,
