fn update_place_ops_in_log_one_inductive(pre: Self, post: Self, node_id: NodeId, rid: ReqId) {
    assert(post.combiner_states_wf()) by {
        assert forall |n| #[trigger] post.combiner.contains_key(n) implies post.wf_combiner_for_node_id(n) by {
            if n == node_id {
                match post.combiner[n] {
                    CombinerState::Placed { queued_ops } => {
                        LogRangeMatchesQueue_append(pre.combiner[node_id].get_Placed_queued_ops(), pre.log, post.log, 0, pre.local_versions[node_id], pre.tail, node_id, pre.local_updates, post.local_updates, rid, post.log[pre.tail]);
                    },
                    _ => {}
                }
            } else {
                assert(post.combiner[n] == pre.combiner[n]);
                assert(pre.wf_combiner_for_node_id(n));
            }
        }
    }
    assert(post.inv_read_results()) by {
        assert forall |r| #[trigger] post.local_reads.contains_key(r) implies post.read_results_match(post.local_reads[r]) by {
            assert(post.local_reads[r] == pre.local_reads[r]);
            assert(post.read_results_match(post.local_reads[r]));
        }
    }
    assert(post.inv_update_results()) by {
        assert forall |r| #[trigger] post.local_updates.contains_key(r) implies post.update_results_match(post.local_updates[r]) by {
            assert(post.update_results_match(post.local_updates[r]));
        }
    }
    assert(post.replica_state()) by {
        assert forall |n| #[trigger] post.replicas.contains_key(n) implies post.replicas[n] == compute_nrstate_at_version(post.log, post.current_local_version(n)) by {
            assert(post.replicas[n] == pre.replicas[n]);
            assert(post.replicas[n] == compute_nrstate_at_version(post.log, post.current_local_version(n)));
        }
    }
}

